//! TPC-H data set, generated by Trino 431 itself: its `tpch` connector (the
//! reference generator, `dbgen`-compatible) is copied with CTAS into the shared
//! Hive warehouse. Both engines then read the very same Parquet files, written
//! in Trino's file-metastore layout — the layout `CodeLake` must take over.
//!
//! Money columns are `double` in the connector; the TPC-H specification says
//! `decimal(15,2)`, and so do production warehouses, so they are cast.

use std::collections::BTreeMap;
use std::time::Duration;

use serde_json::Value;

use crate::driver::{DriverError, Raw, TrinoClient};
use crate::run::log;

/// Every TPC-H table, smallest first.
pub(crate) const TABLES: [&str; 8] = [
    "region", "nation", "supplier", "customer", "part", "partsupp", "orders", "lineitem",
];

fn rows(raw: Raw) -> Vec<Vec<Value>> {
    match raw {
        Raw::Trino { rows, .. } => rows,
        _ => Vec::new(),
    }
}

fn single_u64(raw: Raw) -> Option<u64> {
    rows(raw).first()?.first()?.as_u64()
}

/// Select list that copies a connector table with TPC-H types.
pub(crate) fn select_list(columns: &[(String, String)]) -> String {
    columns
        .iter()
        .map(|(name, data_type)| {
            if data_type == "double" {
                format!("CAST({name} AS decimal(15,2)) AS {name}")
            } else {
                name.clone()
            }
        })
        .collect::<Vec<_>>()
        .join(", ")
}

/// Creates `<catalog>.<target>.*` from `tpch.<source>.*` where missing and
/// checks every table's row count against the generator.
pub(crate) async fn generate(
    trino: &TrinoClient,
    catalog: &str,
    source: &str,
    target: &str,
    timeout: Duration,
) -> Result<BTreeMap<String, u64>, DriverError> {
    trino
        .execute(
            &format!("CREATE SCHEMA IF NOT EXISTS {catalog}.{target}"),
            timeout,
        )
        .await?;
    let mut counts = BTreeMap::new();
    for table in TABLES {
        let exists = single_u64(
            trino
                .execute(
                    &format!(
                        "SELECT count(*) FROM {catalog}.information_schema.tables \
                         WHERE table_schema = '{target}' AND table_name = '{table}'"
                    ),
                    timeout,
                )
                .await?,
        )
        .unwrap_or(0);
        if exists == 0 {
            let columns: Vec<(String, String)> = rows(
                trino
                    .execute(
                        &format!(
                            "SELECT column_name, data_type FROM tpch.information_schema.columns \
                             WHERE table_schema = '{source}' AND table_name = '{table}' \
                             ORDER BY ordinal_position"
                        ),
                        timeout,
                    )
                    .await?,
            )
            .into_iter()
            .filter_map(|r| Some((r.first()?.as_str()?.to_owned(), r.get(1)?.as_str()?.to_owned())))
            .collect();
            log(&format!(
                "generating {catalog}.{target}.{table} from tpch.{source}"
            ));
            trino
                .execute(
                    &format!(
                        "CREATE TABLE {catalog}.{target}.{table} WITH (format = 'PARQUET') AS \
                         SELECT {} FROM tpch.{source}.{table}",
                        select_list(&columns)
                    ),
                    timeout,
                )
                .await?;
        }
        let expected = single_u64(
            trino
                .execute(&format!("SELECT count(*) FROM tpch.{source}.{table}"), timeout)
                .await?,
        );
        let actual = single_u64(
            trino
                .execute(
                    &format!("SELECT count(*) FROM {catalog}.{target}.{table}"),
                    timeout,
                )
                .await?,
        );
        if expected != actual || actual.is_none() {
            return Err(DriverError::Query(format!(
                "{catalog}.{target}.{table} has {actual:?} rows, the generator {expected:?}; \
                 drop the schema and generate again"
            )));
        }
        counts.insert(table.to_owned(), actual.unwrap_or_default());
    }
    Ok(counts)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn money_columns_become_decimals() {
        let columns = vec![
            ("l_orderkey".to_owned(), "bigint".to_owned()),
            ("l_extendedprice".to_owned(), "double".to_owned()),
            ("l_comment".to_owned(), "varchar(44)".to_owned()),
        ];
        assert_eq!(
            select_list(&columns),
            "l_orderkey, CAST(l_extendedprice AS decimal(15,2)) AS l_extendedprice, l_comment"
        );
    }
}
